'use client'

import { useState } from 'react'
import { useLang } from '@/lib/LanguageContext'

export type MyReview = {
  id: string
  star_rating: number
  review_text: string | null
  created_at: string
}

// Shown on the order detail page once an order is completed. Lets the buyer
// rate the produce they ordered (one review per order), or shows the review
// they already left.
export default function ProduceReviewBox({
  orderId,
  produceName,
  existing,
}: {
  orderId: string
  produceName: string
  existing: MyReview | null
}) {
  const { L } = useLang()
  const [review, setReview] = useState<MyReview | null>(existing)
  const [rating, setRating] = useState(0)
  const [hover, setHover] = useState(0)
  const [text, setText] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')

  const submit = async () => {
    if (rating === 0) { setError(L('Please tap a star to rate.', 'రేటింగ్ కోసం స్టార్ నొక్కండి.')); return }
    setSubmitting(true)
    setError('')
    const res = await fetch('/api/produce-reviews', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({ order_id: orderId, star_rating: rating, review_text: text.trim() || null }),
    }).catch(() => null)
    const json = await res?.json().catch(() => ({})) as { review?: MyReview; error?: string }
    setSubmitting(false)
    if (!res || !res.ok || !json.review) {
      setError(json?.error === 'already_reviewed'
        ? L('You already reviewed this order.', 'మీరు ఇప్పటికే ఈ ఆర్డర్‌ను సమీక్షించారు.')
        : (json?.error ?? L('Could not submit. Try again.', 'సమర్పించలేకపోయాం. మళ్ళీ ప్రయత్నించండి.')))
      return
    }
    setReview(json.review)
  }

  if (review) {
    return (
      <div className="bg-green-50 border border-green-200 rounded-2xl p-4">
        <p className="text-xs font-bold text-green-700 uppercase tracking-wide mb-1">
          ⭐ {L('Your rating', 'మీ రేటింగ్')}
        </p>
        <div className="flex items-center gap-0.5">
          {[1, 2, 3, 4, 5].map((s) => (
            <span key={s} className={`text-xl ${s <= review.star_rating ? 'text-yellow-400' : 'text-gray-300'}`}>★</span>
          ))}
        </div>
        {review.review_text && (
          <p className="text-sm text-gray-700 mt-2 leading-relaxed">{review.review_text}</p>
        )}
        <p className="text-[11px] text-green-700 mt-2">
          {L('Thanks for helping other buyers!', 'ఇతర కొనుగోలుదారులకు సహాయం చేసినందుకు ధన్యవాదాలు!')}
        </p>
      </div>
    )
  }

  return (
    <div className="bg-white border border-gray-200 rounded-2xl p-4">
      <p className="text-sm font-extrabold text-gray-900">
        {L('Rate', 'రేటింగ్ ఇవ్వండి')} {produceName}
      </p>
      <p className="text-[11px] text-gray-500 mt-0.5 mb-3">
        {L('How was it? Your review helps other buyers.', 'ఎలా ఉంది? మీ సమీక్ష ఇతర కొనుగోలుదారులకు సహాయపడుతుంది.')}
      </p>

      <div className="flex gap-1 mb-3">
        {[1, 2, 3, 4, 5].map((s) => (
          <button
            key={s}
            type="button"
            onClick={() => setRating(s)}
            onMouseEnter={() => setHover(s)}
            onMouseLeave={() => setHover(0)}
            className="text-4xl leading-none transition-transform active:scale-110"
            aria-label={`${s} stars`}
          >
            <span className={(hover || rating) >= s ? 'text-yellow-400' : 'text-gray-200'}>★</span>
          </button>
        ))}
      </div>

      <textarea
        value={text}
        onChange={(e) => setText(e.target.value.slice(0, 600))}
        placeholder={L('Share a few words (optional)', 'కొన్ని మాటలు రాయండి (ఐచ్ఛికం)')}
        rows={3}
        className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm resize-none focus:border-green-500 focus:outline-none"
      />

      {error && <p className="text-sm text-red-600 bg-red-50 rounded-xl px-3 py-2 mt-2">{error}</p>}

      <button
        type="button"
        onClick={submit}
        disabled={submitting}
        className="mt-3 w-full bg-green-700 text-white font-bold py-3 rounded-xl text-sm disabled:opacity-50 active:bg-green-800"
      >
        {submitting ? L('Submitting…', 'సమర్పిస్తోంది…') : L('Submit rating', 'రేటింగ్ సమర్పించు')}
      </button>
    </div>
  )
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function admin() {
  return createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!)
}

// Recompute and cache a listing's rating aggregate after a review changes.
async function refreshAggregate(supabase: ReturnType<typeof admin>, listingId: string) {
  const { data: rows } = await supabase
    .from('produce_reviews')
    .select('star_rating')
    .eq('produce_listing_id', listingId)
    .eq('approved', true)
  const count = rows?.length ?? 0
  const avg = count > 0
    ? Math.round((rows!.reduce((s, r: { star_rating: number }) => s + r.star_rating, 0) / count) * 10) / 10
    : null
  await supabase
    .from('produce_listings')
    .update({ rating_avg: avg, review_count: count })
    .eq('id', listingId)
}

// GET /api/produce-reviews?listing_id=<uuid>
// Public — returns approved reviews + aggregate for a produce listing.
export async function GET(req: NextRequest) {
  const listingId = new URL(req.url).searchParams.get('listing_id') ?? ''
  if (!UUID_RE.test(listingId)) {
    return NextResponse.json({ error: 'Invalid listing id.' }, { status: 400 })
  }

  const supabase = admin()
  const { data: reviews, error } = await supabase
    .from('produce_reviews')
    .select('id, reviewer_name, star_rating, review_text, created_at')
    .eq('produce_listing_id', listingId)
    .eq('approved', true)
    .order('created_at', { ascending: false })
    .limit(100)

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })

  const count = reviews?.length ?? 0
  const avg = count > 0
    ? Math.round((reviews!.reduce((s, r) => s + r.star_rating, 0) / count) * 10) / 10
    : null

  return NextResponse.json({ reviews: reviews ?? [], rating_avg: avg, review_count: count })
}

// POST /api/produce-reviews
// Verified buyer leaves a review on a produce they ordered, once the order is
// delivered / picked up. Body: { order_id, star_rating, review_text? }.
export async function POST(req: NextRequest) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })

  let body: { order_id?: unknown; star_rating?: unknown; review_text?: unknown }
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid request.' }, { status: 400 })
  }

  const orderId = typeof body.order_id === 'string' ? body.order_id : ''
  if (!UUID_RE.test(orderId)) {
    return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })
  }
  const rating = typeof body.star_rating === 'number' ? body.star_rating : NaN
  if (!Number.isInteger(rating) || rating < 1 || rating > 5) {
    return NextResponse.json({ error: 'Rating must be 1-5.' }, { status: 400 })
  }
  const text = typeof body.review_text === 'string' ? body.review_text.trim().slice(0, 600) : ''

  const supabase = admin()

  const { data: order, error: orderErr } = await supabase
    .from('orders')
    .select('id, consumer_id, produce_listing_id, farmer_id, buyer_name, buyer_phone, status, received_at, collected_at, delivered_at, delivery_status')
    .eq('id', orderId)
    .maybeSingle()

  if (orderErr) return NextResponse.json({ error: orderErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  if (!order.produce_listing_id) {
    return NextResponse.json({ error: 'This order cannot be reviewed.' }, { status: 400 })
  }

  // Only completed orders may be reviewed — delivered, picked up, or buyer-
  // confirmed received. Declined/cancelled orders never qualify.
  const completed =
    order.status !== 'declined' &&
    order.status !== 'cancelled' &&
    (!!order.received_at || !!order.collected_at || !!order.delivered_at || order.delivery_status === 'delivered')
  if (!completed) {
    return NextResponse.json({ error: 'You can review after the order is delivered or picked up.' }, { status: 400 })
  }

  // One review per order.
  const { data: existing } = await supabase
    .from('produce_reviews')
    .select('id')
    .eq('order_id', orderId)
    .maybeSingle()
  if (existing) {
    return NextResponse.json({ error: 'already_reviewed' }, { status: 409 })
  }

  const { data: review, error: insErr } = await supabase
    .from('produce_reviews')
    .insert({
      order_id: orderId,
      produce_listing_id: order.produce_listing_id,
      farmer_id: order.farmer_id ?? null,
      consumer_id: order.consumer_id ?? null,
      reviewer_name: (order.buyer_name as string | null)?.trim()?.slice(0, 80) || 'Buyer',
      reviewer_phone: order.buyer_phone ? String(order.buyer_phone).replace(/\D/g, '').slice(-10) : null,
      star_rating: rating,
      review_text: text || null,
      approved: true,
    })
    .select('id, reviewer_name, star_rating, review_text, created_at')
    .single()

  if (insErr) return NextResponse.json({ error: insErr.message }, { status: 500 })

  await refreshAggregate(supabase, order.produce_listing_id)

  return NextResponse.json({ review })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

export async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error } = await supabase
    .from('orders')
    .select(
      'id, order_code, consumer_id, produce_name, produce_listing_id, quantity, unit, total_price, pickup_location, status, payment_method, payment_method_detail, payment_status, paid_at, confirmed_at, razorpay_payment_id, refund_status, refund_id, refund_amount, refunded_at, decline_reason, payment_proof_path, created_at, farmer_id, delivery_type, delivery_status, delivery_address, delivery_landmark, delivery_pincode, delivery_alt_phone, delivery_boy_id, handover_otp, assigned_at, picked_up_at, out_for_delivery_at, delivered_at, collected_at, shipped_at, received_at, fulfillment_date',
    )
    .eq('id', id)
    .maybeSingle()

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }

  // Manual farmer join (no FK on orders.farmer_id → farmers.id, so embedding fails)
  let farmer: { name: string; slug: string; village: string; phone: string | null; upi_id: string | null } | null = null
  if (order.farmer_id) {
    const { data: f } = await supabase
      .from('farmers')
      .select('id, name, slug, village, phone, upi_id')
      .eq('id', order.farmer_id)
      .maybeSingle()
    if (f) {
      farmer = {
        name: f.name,
        slug: f.slug,
        village: f.village,
        phone: f.phone ?? null,
        upi_id: (f.upi_id as string | null) ?? null,
      }
    }
  }

  // Rider contact (only after a rider has been assigned). Minimal exposure:
  // name + phone, nothing else.
  let rider: { id: string; name: string | null; phone: string } | null = null
  const dbi = (order as { delivery_boy_id?: string | null }).delivery_boy_id ?? null
  if (dbi) {
    const { data: r } = await supabase
      .from('delivery_boys')
      .select('id, name, phone')
      .eq('id', dbi)
      .maybeSingle()
    if (r) rider = { id: r.id, name: r.name ?? null, phone: r.phone }
  }

  // The buyer's own produce review for this order, if they've left one. Drives
  // the "Rate this produce" box on the order detail page.
  let myReview: { id: string; star_rating: number; review_text: string | null; created_at: string } | null = null
  const { data: rev } = await supabase
    .from('produce_reviews')
    .select('id, star_rating, review_text, created_at')
    .eq('order_id', order.id)
    .maybeSingle()
  if (rev) myReview = rev

  return NextResponse.json({ order: { ...order, farmer, rider, my_review: myReview } })
}

